let earningsPro='',observationType='',reportSport='',reportClub='';
function earnings(){const companyRows=(data.companyHours||[]).filter(r=>!admin()||!earningsPro||r.professional_id===earningsPro);const companyCommission=companyRows.reduce((sum,r)=>sum+(r.commission_cents||0),0);const rows=(data.earnings||[]).filter(e=>!admin()||!earningsPro||e.therapist_id===earningsPro);const total=k=>rows.reduce((s,e)=>s+e[k],0);const pending=rows.reduce((s,e)=>s+Math.max(0,e.received_share_cents-e.paid_out_cents),0);return title('Meus rendimentos',admin()?'Previsão e repasses dos profissionais.':'Sua previsão mensal e seus repasses, sem acesso ao financeiro geral.',admin()?'<button data-action="payout-rules">Configurar percentuais</button>':'')+monthControl()+(admin()?`<div class="toolbar">${select('earnings_pro','Profissional',[['','Todos os profissionais'],...data.profiles.map(p=>[p.user_id,p.name])],earningsPro)}</div>`:'')+`<div class="stats">${stat('Previsão contratada',money(total('commission_cents')+companyCommission),'Pacientes + empresas com percentuais definidos')}${stat('Correspondente ao recebido',money(total('received_share_cents')),'Calculado sobre o pagamento dos pacientes')}${stat('Repasses pagos',money(total('paid_out_cents')),'Registrados pelo gestor')}${stat('Saldo sobre recebido',money(pending),'Ainda sem repasse registrado')}</div><div class="card"><h2>Como seu rendimento é calculado</h2><p>As deduções de nota e sala incidem separadamente sobre o valor bruto. O percentual do profissional é aplicado ao líquido. Estes percentuais são parâmetros do acordo com a NEAR.</p><p style="margin-top:12px"><strong>Exemplo: R$ 500,00 − 6% de nota − 15% de sala = R$ 395,00 líquidos. Repasse de 60% = R$ 237,00.</strong></p><p class="sub" style="margin-top:10px">A previsão não é confirmação de pagamento. Repetir sessões na agenda não cria pacotes ou repasses automaticamente.</p></div><div class="card"><table><thead><tr><th>Atendimento / paciente</th>${admin()?'<th>Profissional</th>':''}<th>Bruto</th><th>Nota</th><th>Sala</th><th>Líquido</th><th>Seu percentual</th><th>Previsto</th><th>Sobre recebido</th><th>Repasse pago</th>${admin()?'<th></th>':''}</tr></thead><tbody>${rows.map(e=>`<tr><td>${h(e.patient_name)}</td>${admin()?`<td>${h(professional(e.therapist_id))}</td>`:''}<td>${money(e.gross_cents)}</td><td>${e.tax_bps/100}%<br>${money(e.tax_cents)}</td><td>${e.room_bps/100}%<br>${money(e.room_cents)}</td><td>${money(e.net_cents)}</td><td>${e.share_bps/100}%</td><td><strong>${money(e.commission_cents)}</strong></td><td>${money(e.received_share_cents)}</td><td>${money(e.paid_out_cents)}</td>${admin()?`<td><button data-action="payout" data-id="${e.patient_id}">Registrar repasse</button></td>`:''}</tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">Nenhum pacote mensal de paciente vinculado a este profissional.</div>':''}</div>`+companyEarningsTable(companyRows)}
function payoutRulesForm(){if(!admin())return;const pro=earningsPro||data.profiles.find(p=>p.role==='therapist')?.user_id||user.id,r=(data.payoutRules||[]).find(r=>r.therapist_id===pro)||{tax_bps:600,room_bps:1500,share_bps:6000};modal('Percentuais de rendimento',monthLabel()+' · aplicados aos pacotes do profissional neste mês.',select('therapist_id','Profissional',data.profiles.map(p=>[p.user_id,p.name]),pro)+`<div class="formgrid">${field('tax','Nota / imposto (%)',r.tax_bps/100,'number',true)}${field('room','Sala / clube (%)',r.room_bps/100,'number',true)}${field('share','Percentual do profissional (%)',r.share_bps/100,'number',true)}</div><p class="sub" style="margin-top:18px">Padrão: 6%, 15% e 60%. Para outro profissional, os valores mostrados são uma proposta até que sejam salvos. Repasses pagos não são apagados ao recalcular.</p>`,async d=>{const tax=Math.round(Number(d.tax)*100),room=Math.round(Number(d.room)*100),share=Math.round(Number(d.share)*100);if([tax,room,share].some(n=>!Number.isInteger(n)||n<0||n>10000)||tax+room>10000)throw Error('Confira os percentuais. Nota e sala não podem ultrapassar 100% juntos.');const res=await client.from('near_test_payout_rules').upsert({therapist_id:d.therapist_id,month:monthDate(),tax_bps:tax,room_bps:room,share_bps:share}).select('therapist_id').single();if(res.error)throw Error('Não foi possível recalcular: '+res.error.message);earningsPro=d.therapist_id});$('#f-therapist_id').onchange=()=>{const rule=(data.payoutRules||[]).find(r=>r.therapist_id===$('#f-therapist_id').value)||{tax_bps:600,room_bps:1500,share_bps:6000};$('#f-tax').value=rule.tax_bps/100;$('#f-room').value=rule.room_bps/100;$('#f-share').value=rule.share_bps/100}}
