function observations(){const all=(data.observations||[]).filter(o=>!observationType||o.type===observationType);return title('Treinos e dinâmicas','Registre o acompanhamento e prepare a síntese institucional do mês.','<button class="primary" data-action="observation">＋ Novo acompanhamento</button>')+monthControl()+`<div class="toolbar">${select('observation_type','Tipo',[['','Todos'],['Treino','Treino'],['Dinâmica de grupo','Dinâmica de grupo']],observationType)}</div><div class="stats">${stat('Registros no mês',all.length,'Disponíveis para sua conta')}${stat('Treinos',all.filter(o=>o.type==='Treino').length,'Acompanhamentos')}${stat('Dinâmicas',all.filter(o=>o.type==='Dinâmica de grupo').length,'Intervenções em grupo')}${stat('Para o relatório',all.filter(o=>o.include_report).length,'Com síntese institucional selecionada')}</div>${all.map(o=>`<div class="card"><div class="cardhead"><div><h2>${h(o.sport)} · ${h(o.category||'Categoria não informada')}</h2><small>${dateBR(o.date)} · ${h(o.time.slice(0,5))} · ${h(o.type)} · ${h(professional(o.author_id))}</small></div>${o.author_id===user.id?`<button data-action="observation" data-id="${o.id}">Editar registro</button>`:''}</div><p><strong>${h(o.activity||'Acompanhamento de treino')}</strong></p><p style="margin-top:12px">${o.participants===null?'Número de participantes não informado':o.participants+' participações'} · Treinador presente: ${h(o.coach_presence)}</p><h3 style="margin-top:22px">Observações internas</h3><p style="white-space:pre-wrap;margin-top:8px">${h(o.observations)}</p><h3 style="margin-top:22px">Síntese para o clube ${o.include_report?'· incluída no relatório':'· não incluída'}</h3><p style="white-space:pre-wrap;margin-top:8px">${h(o.report_summary||'Não preenchida')}</p>${o.photo_paths?.length?`<button class="link" style="margin-top:18px" data-action="photos" data-id="${o.id}">Ver ${o.photo_paths.length} foto(s) privada(s)</button>`:''}</div>`).join('')}${!all.length?'<div class="card empty">Nenhum acompanhamento registrado neste mês.</div>':''}`}
function observationForm(id){const o=data.observations.find(o=>o.id===id)||{},newObs=!id;modal(id?'Editar acompanhamento':'Novo acompanhamento','O autor é identificado pela conta conectada. Observações internas não entram automaticamente no relatório.',`<div class="formgrid">${select('type','Tipo de registro',['Treino','Dinâmica de grupo'],o.type||'Treino')}${field('club','Clube',o.club||'Grêmio Náutico União','text',true)}${field('date','Data da observação',o.date||dateISO(),'date',true)}${field('time','Horário',o.time?.slice(0,5)||'09:00','time',true)}${field('duration_minutes','Duração do acompanhamento (minutos)',o.duration_minutes||0,'number')}${field('co_observers','Outros observadores',o.co_observers)}${field('sport','Modalidade esportiva',o.sport,'text',true)}${field('category','Categoria da modalidade',o.category)}${field('participants','Quantos atletas participaram?',o.participants??'','number')}${field('coaches','Treinadores da equipe',o.coaches)}${select('coach_presence','O treinador estava presente?',['Sim','Não','Parcial'],o.coach_presence||'Sim')}</div>`+field('activity','Dinâmica aplicada / atividade observada',o.activity)+area('objective','Objetivo da dinâmica ou do acompanhamento',o.objective)+area('observations','Observações internas: comportamentos, atitudes e emoções',o.observations)+area('communication','Comunicação observada no grupo',o.communication)+area('next_steps','Pontos fortes, fragilidades e possíveis evoluções',o.next_steps)+section('Síntese institucional para o relatório do clube')+area('report_summary','Síntese coletiva para o clube — sem nomes ou dados clínicos individuais',o.report_summary)+area('report_next_steps','Recomendações institucionais e próximos passos',o.report_next_steps)+select('include_report','Incluir esta síntese automaticamente no rascunho mensal?',[['true','Sim'],['false','Não, manter apenas no acompanhamento']],String(o.include_report??true))+section('Fotos privadas')+'<label for="observation-photo">Adicionar uma foto (JPEG, PNG ou WebP, até 5 MB)</label><input id="observation-photo" type="file" accept="image/jpeg,image/png,image/webp"><p class="sub" style="margin-top:12px">Use somente fotos com autorização. Elas ficam privadas e não entram automaticamente no relatório. Fotos já salvas são preservadas.</p>',async d=>{const count=d.participants===''?null:Number(d.participants),duration=Number(d.duration_minutes||0);if((count!==null&&(!Number.isInteger(count)||count<0||count>10000))||!Number.isInteger(duration)||duration<0||duration>1440)throw Error('Confira participantes e duração.');if(d.include_report==='true'&&!d.report_summary.trim())throw Error('Preencha a síntese institucional ou escolha não incluir no relatório.');let photos=[...(o.photo_paths||[])];const photo=$('#observation-photo').files[0];if(photo){const allowed={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'};if(!allowed[photo.type]||photo.size>5*1024*1024)throw Error('A foto precisa ser JPEG, PNG ou WebP e ter até 5 MB.');const path=user.id+'/'+crypto.randomUUID()+'.'+allowed[photo.type];const up=await client.storage.from('near-observacoes').upload(path,photo,{contentType:photo.type,upsert:false});if(up.error)throw Error('Foto não enviada: '+up.error.message);photos.push(path)}const row={...d,id:id||crypto.randomUUID(),author_id:user.id,participants:count,duration_minutes:duration,include_report:d.include_report==='true',photo_paths:photos,updated_at:new Date().toISOString()};const r=await client.from('near_test_observations').upsert(row).select('id').single();if(r.error)throw Error(r.error.message)})}
async function showPhotos(id){const o=data.observations.find(o=>o.id===id);modal('Fotos do acompanhamento','Acesso privado. Os links expiram em 60 segundos.','<div id="private-photos">Carregando…</div>',async()=>{});$('#save').hidden=true;$('#cancel').textContent='Fechar';try{const links=await Promise.all(o.photo_paths.map(async path=>{const r=await client.storage.from('near-observacoes').createSignedUrl(path,60);if(r.error)throw Error(r.error.message);return r.data.signedUrl}));$('#private-photos').innerHTML=links.map(url=>`<img alt="Foto privada do acompanhamento" src="${h(url)}" style="width:100%;margin:15px 0;border-radius:7px">`).join('')}catch(e){if($('#private-photos'))$('#private-photos').textContent=e.message}}
