function buildClubReport(rows){const title='RELATÓRIO MENSAL DE ACOMPANHAMENTO PSICOLÓGICO NO ESPORTE';const mins=rows.reduce((s,o)=>s+o.duration_minutes,0),counts=rows.filter(o=>o.participants!==null),participations=counts.reduce((s,o)=>s+o.participants,0);let lines=[title,'NEAR · Gestão em Psicologia','Período: '+monthLabel(),'Clube: '+(reportClub||'Conforme ações relacionadas'),'Modalidade: '+(reportSport||'Modalidades relacionadas'),'Elaborado por: '+profile.name,'Escopo: '+(admin()?'sínteses institucionais disponibilizadas pela equipe.':'sínteses institucionais dos meus próprios acompanhamentos.'),'','1. Síntese das ações',`${rows.length} registros de acompanhamento: ${rows.filter(o=>o.type==='Treino').length} treinos e ${rows.filter(o=>o.type==='Dinâmica de grupo').length} dinâmicas de grupo.`,`Tempo somado dos registros de acompanhamento: ${Math.floor(mins/60)}h ${mins%60}min.`,`Participações registradas: ${participations}. Soma de presenças nas ações; não representa atletas únicos.`,counts.length<rows.length?`${rows.length-counts.length} ação(ões) sem número de participantes informado.`:'','', '2. Acompanhamentos por modalidade'];for(const sport of [...new Set(rows.map(o=>o.sport))]){lines.push('',sport);for(const o of rows.filter(o=>o.sport===sport)){lines.push(`${dateBR(o.date)} · ${o.time.slice(0,5)} · ${o.type} · ${o.category||'Categoria não informada'}`,`Atividade: ${o.activity||'Acompanhamento de treino'}`);if(o.objective.trim())lines.push('Objetivo: '+o.objective.trim());lines.push('Síntese institucional: '+o.report_summary.trim());if(o.report_next_steps.trim())lines.push('Recomendações: '+o.report_next_steps.trim())}}lines.push('','3. Próximos passos',...rows.filter(o=>o.report_next_steps.trim()).map(o=>o.sport+' / '+o.category+': '+o.report_next_steps.trim()));if(!rows.some(o=>o.report_next_steps.trim()))lines.push('Recomendações institucionais ainda não registradas.');lines.push('','Rascunho para revisão do responsável técnico antes de qualquer envio ao clube.');return lines.filter((x,i)=>x!==''||lines[i-1]!=='').join('\n')}
function clubReport(){const rows=institutionRows(),sports=[...new Set((data.observations||[]).map(o=>o.sport))].sort(),clubs=[...new Set((data.observations||[]).map(o=>o.club))].sort();return title('Relatório do clube','Rascunho gerado automaticamente a partir das sínteses institucionais selecionadas.')+monthControl()+`<div class="formgrid report-filters">${select('report_club','Clube',[['','Todos os clubes'],...clubs],reportClub)}${select('report_sport','Modalidade',[['','Todas as modalidades'],...sports],reportSport)}</div><div class="card"><div class="cardhead"><div><h2>Rascunho atualizado · ${rows.length} ações</h2><p class="sub">Observações internas, prontuários, financeiro e fotos ficam fora deste texto.</p></div><button data-action="regenerate-report">Gerar novamente</button></div>${!rows.length?'<p class="notice">Não há sínteses selecionadas para estes filtros. Preencha um acompanhamento e marque a inclusão no relatório.</p>':''}<label for="report-body">Revise e edite o texto antes de salvar ou imprimir</label><textarea id="report-body" class="report-editor">${h(buildClubReport(rows))}</textarea><div class="preview-actions"><button class="primary" data-action="save-report">Salvar versão revisada</button><button data-action="print-report">Imprimir / Salvar como PDF</button></div><p class="sub">O texto acima é atualizado ao abrir esta aba ou gerar novamente. Versões salvas são fotografias do momento e não são sobrescritas por novos registros.</p></div><div class="card"><h2>Versões salvas neste mês</h2>${(data.clubReports||[]).map(r=>`<div class="event"><strong>${h(r.title)}</strong><small>${h(professional(r.author_id))} · ${new Date(r.updated_at).toLocaleString('pt-BR')}</small><br><button class="link" data-action="open-report" data-id="${r.id}">Abrir versão</button></div>`).join('')||'<p>Nenhuma versão salva.</p>'}</div>`}
async function saveReport(){try{const body=$('#report-body').value;if(!body.trim())throw Error('O relatório está vazio.');const rows=institutionRows(),r=await client.from('near_test_club_reports').insert({author_id:user.id,month:monthDate(),club:reportClub||'Clubes relacionados',sport:reportSport,title:'Relatório · '+monthLabel()+(reportSport?' · '+reportSport:''),body,source_ids:rows.map(o=>o.id)}).select('id').single();if(r.error)throw Error(r.error.message);await reload();message('Versão salva. O texto permanece nesta tela para impressão.');const text=body;render();$('#report-body').value=text}catch(e){message(e.message)}}
function printReport(text){const body=text||$('#report-body')?.value;if(!body?.trim()){message('Não há texto para imprimir.');return}let paper=$('#print-area');if(!paper){paper=document.createElement('article');paper.id='print-area';document.body.appendChild(paper)}paper.innerHTML='<h1>NEAR</h1><div class="print-body">'+h(body)+'</div>';window.print()}
function openSavedReport(id){const r=data.clubReports.find(r=>r.id===id);modal(r.title,'Versão salva · revise antes de enviar ao clube.',area('body','Texto salvo',r.body,true)+'<button type="button" id="print-saved" style="margin-top:18px">Imprimir / PDF</button>',async d=>{if(r.author_id!==user.id)throw Error('Somente o autor pode alterar esta versão. Gere uma nova versão pela sua conta.');const up=await client.from('near_test_club_reports').update({body:d.body,updated_at:new Date().toISOString()}).eq('id',id).select('id').single();if(up.error)throw Error(up.error.message)});$('#print-saved').onclick=()=>printReport($('#f-body').value);if(r.author_id!==user.id)$('#save').hidden=true}
function profilePage(){return title('Meu perfil','Identificação e contato para receber confirmações de horário.')+`<div class="card"><h2>${h(profile.name)}</h2><p>${admin()?'Gestor':'Profissional da equipe'}</p><p style="margin-top:18px">WhatsApp: ${h(profile.phone||'Não informado')}</p><p>Recebimento autorizado: ${profile.whatsapp_opt_in?'Sim':'Não'}</p><button style="margin-top:20px" data-action="profile-contact">Editar meu WhatsApp</button></div><div class="card"><h2>Avisos de sessão</h2><p>Na agenda, abra o botão WhatsApp de uma sessão para preparar uma mensagem ao paciente/responsável ou ao profissional. O envio é manual e precisa ser confirmado no WhatsApp.</p></div>`}
function profileContactForm(){modal('Meu WhatsApp','Seu número será usado apenas para preparar avisos das sessões.',field('phone','Número com DDD e país (ex.: 55 51 …)',profile.phone,'tel')+select('whatsapp_opt_in','Autorizo receber avisos das minhas sessões',[['false','Não'],['true','Sim']],String(profile.whatsapp_opt_in||false)),async d=>{const r=await client.from('near_test_profiles').update({phone:d.phone,whatsapp_opt_in:d.whatsapp_opt_in==='true'}).eq('user_id',user.id).select('user_id').single();if(r.error)throw Error(r.error.message)})}
function normalizePhone(value){let s=String(value||'').replace(/\D/g,'');if([10,11].includes(s.length))s='55'+s;return s.length>=12&&s.length<=15?s:null}
function whatsappForm(id){const a=data.appointments.find(a=>a.id===id),p=person(a.patient_id),pro=data.profiles.find(p=>p.user_id===a.therapist_id),parts=localParts(a.starts_at);const patientText=a.status==='Cancelado'?`Olá! Informamos que o atendimento de ${dateBR(parts.date)}, às ${parts.time}, foi cancelado. Entre em contato para combinar os próximos passos. NEAR.`:`Olá! Lembrete do seu atendimento em ${dateBR(parts.date)}, às ${parts.time}, com ${professional(a.therapist_id)}. Se precisar ajustar o horário, entre em contato. NEAR.`;const professionalText=`Olá, ${professional(a.therapist_id)}! ${a.status==='Cancelado'?'Cancelamento':'Lembrete'}: sessão de ${dateBR(parts.date)}, às ${parts.time}. Consulte o sistema NEAR para os detalhes.`;modal('Aviso por WhatsApp','Escolha o contato autorizado e revise a mensagem. Não há envio automático.',select('recipient','Destinatário',[['patient','Paciente / responsável'],['professional','Profissional']],'patient')+'<p class="sub" id="wa-contact" style="margin-top:15px"></p>'+area('text','Mensagem',patientText)+'<div id="wa-link" style="margin-top:20px"></div>',async()=>{});$('#save').hidden=true;$('#cancel').textContent='Fechar';function update(){const who=$('#f-recipient').value,isPatient=who==='patient',allowed=isPatient?p.whatsapp_authorized:pro?.whatsapp_opt_in,phone=isPatient?p.whatsapp_phone:pro?.phone,name=isPatient?(p.whatsapp_contact||p.guardian||'Contato do paciente'):professional(a.therapist_id);$('#wa-contact').textContent=name+' · '+(phone||'Número não cadastrado');const n=normalizePhone(phone);$('#wa-link').innerHTML=allowed&&n?`<a class="button primary" target="_blank" rel="noopener noreferrer" id="wa-open" href="https://wa.me/${n}?text=${encodeURIComponent($('#f-text').value)}">Abrir WhatsApp e revisar envio</a><p class="sub" style="margin-top:12px">O WhatsApp abrirá com o texto preenchido. Você decide quando enviar.</p>`:`<p class="notice">${!allowed?'Contato sem autorização registrada.':'Cadastre um número válido com DDD.'} ${isPatient?'Edite as preferências no cadastro do paciente.':'O profissional configura o contato em Meu perfil.'}</p>`}$('#f-recipient').onchange=()=>{$('#f-text').value=$('#f-recipient').value==='patient'?patientText:professionalText;update()};$('#f-text').oninput=update;update()}

function companies(){const hours=data.companyHours||[],mins=hours.reduce((s,r)=>s+r.minutes,0),gross=hours.reduce((s,r)=>s+r.gross_cents,0),known=hours.filter(r=>r.commission_cents!==null),repasse=known.reduce((s,r)=>s+r.commission_cents,0);return title('Empresas e horas','Registre os serviços, o tempo trabalhado e o valor de cada atendimento empresarial.',`<div class="preview-actions"><button data-action="company">＋ Nova empresa</button><button class="primary" data-action="company-hour">＋ Lançar horas</button></div>`)+monthControl()+`<div class="stats">${stat('Empresas',data.companies.length,'Visíveis na sua conta')}${stat('Horas registradas',(mins/60).toLocaleString('pt-BR',{maximumFractionDigits:2})+' h',monthLabel())}${stat('Valor dos serviços',money(gross),'Horas × valor por hora')}${stat('Repasse previsto',money(repasse),hours.length-known.length+' lançamento(s) com percentual a definir')}</div><div class="card"><h2>Empresas cadastradas</h2><table><thead><tr><th>Empresa</th><th>Profissional</th><th>Referência por hora</th><th></th></tr></thead><tbody>${data.companies.map(c=>`<tr><td><strong>${h(c.name)}</strong><br><small>${h(c.contact)}</small></td><td>${h(professional(c.professional_id))}</td><td>${money(c.hourly_rate_cents)}</td><td><button data-action="company" data-id="${c.id}">Editar</button>${admin()?` <button data-action="company-rule" data-id="${c.id}">Definir repasse</button>`:''}</td></tr>`).join('')}</tbody></table>${!data.companies.length?'<div class="empty">Cadastre uma empresa para começar.</div>':''}</div><div class="card"><h2>Lançamentos de '+monthLabel()+'</h2><table><thead><tr><th>Data / empresa</th><th>Profissional</th><th>Horas</th><th>Valor / hora</th><th>Valor do serviço</th><th>Repasse previsto</th><th></th></tr></thead><tbody>${hours.map(r=>`<tr><td>${dateBR(r.date)} · <strong>${h(r.company_name)}</strong><br><small>${h(r.activity)}</small></td><td>${h(professional(r.professional_id))}</td><td>${(r.minutes/60).toLocaleString('pt-BR',{maximumFractionDigits:2})} h<br><small>${r.started_at?r.started_at.slice(0,5)+'–'+r.ended_at.slice(0,5):'Horas informadas'}${r.break_minutes?' · pausa '+r.break_minutes+' min':''}</small></td><td>${money(r.rate_cents)}</td><td>${money(r.gross_cents)}</td><td>${r.commission_cents===null?'A definir':money(r.commission_cents)+' ('+r.share_bps/100+'%)'}</td><td><button data-action="company-hour" data-id="${r.id}">Editar</button></td></tr>`).join('')}</tbody></table>${!hours.length?'<div class="empty">Nenhuma hora lançada neste mês.</div>':''}<p class="sub" style="margin-top:18px">Valores empresariais são separados dos atendimentos de pacientes. O repasse aparece após o gestor configurar nota, sala/custos e percentual para esta empresa e mês. Registrar horas não envia cobrança nem confirma recebimento.</p></div>`}
function companyForm(id){const c=data.companies.find(c=>c.id===id)||{};modal(id?'Editar empresa':'Nova empresa','O profissional vê somente as empresas vinculadas à própria conta.',field('name','Nome da empresa',c.name,'text',true)+`<div class="formgrid">${field('document','CNPJ (opcional)',c.document)}${field('contact','Contato na empresa',c.contact)}${field('phone','Telefone',c.phone,'tel')}${field('email','E-mail',c.email,'email')}${field('hourly_rate','Valor de referência por hora (R$)',((c.hourly_rate_cents||0)/100).toFixed(2),'number',true)}${admin()?select('professional_id','Profissional responsável',data.profiles.map(p=>[p.user_id,p.name]),c.professional_id||user.id):''}${select('active','Situação',[['true','Ativa'],['false','Inativa']],String(c.active??true))}</div>`,async d=>{const rate=Math.round(Number(d.hourly_rate)*100);if(!Number.isSafeInteger(rate)||rate<0)throw Error('Informe um valor por hora válido.');const row={...d,id:id||crypto.randomUUID(),professional_id:admin()?d.professional_id:user.id,hourly_rate_cents:rate,active:d.active==='true'};delete row.hourly_rate;const r=await client.from('near_test_companies').upsert(row).select('id').single();if(r.error)throw Error(r.error.message)})}
function companyHoursForm(id){if(!data.companies.length){message('Cadastre uma empresa antes de lançar as horas.');companyForm();return}const r=data.companyHours.find(r=>r.id===id)||{},c=data.companies.find(c=>c.id===r.company_id)||data.companies.find(c=>c.active)||data.companies[0];modal(id?'Editar horas da empresa':'Lançar horas de empresa','O valor do serviço é calculado pelas horas trabalhadas e pelo valor por hora.',select('company_id','Empresa',data.companies.filter(c=>c.active||c.id===r.company_id).map(c=>[c.id,c.name+' · '+professional(c.professional_id)]),r.company_id||c.id)+field('date','Data',r.date||dateISO(),'date',true)+select('mode','Como informar o tempo',[['manual','Quantidade de horas'],['time','Horário de início e fim']],r.started_at?'time':'manual')+`<div id="company-manual">${field('hours','Horas trabalhadas (ex.: 1,5 = 1h30)',r.minutes?r.minutes/60:1,'number')}</div><div id="company-timed" class="formgrid">${field('started_at','Início',r.started_at?.slice(0,5)||'08:00','time')}${field('ended_at','Fim',r.ended_at?.slice(0,5)||'10:00','time')}${field('break_minutes','Intervalo / pausa em minutos',r.break_minutes||0,'number')}</div>`+field('rate','Valor por hora neste serviço (R$)',((r.rate_cents??c.hourly_rate_cents)/100).toFixed(2),'number',true)+area('activity','Atividade / descrição do serviço',r.activity)+'<p id="company-preview" class="notice"></p>',async d=>{let minutes;if(d.mode==='time'){if(!d.started_at||!d.ended_at||d.ended_at<=d.started_at)throw Error('O horário de fim deve ser posterior ao início, no mesmo dia.');const t=v=>Number(v.slice(0,2))*60+Number(v.slice(3));minutes=t(d.ended_at)-t(d.started_at)-Number(d.break_minutes||0)}else minutes=Math.round(Number(d.hours)*60);const rate=Math.round(Number(d.rate)*100);if(!Number.isInteger(minutes)||minutes<1||minutes>1440||!Number.isSafeInteger(rate)||rate<0)throw Error('Confira as horas e o valor por hora.');const row={company_id:d.company_id,date:d.date,minutes,rate_cents:rate,activity:d.activity,started_at:d.mode==='time'?d.started_at:null,ended_at:d.mode==='time'?d.ended_at:null,break_minutes:d.mode==='time'?Number(d.break_minutes||0):0};const req=id?client.from('near_test_company_hours').update(row).eq('id',id):client.from('near_test_company_hours').insert(row);const res=await req.select('id').single();if(res.error)throw Error(res.error.message)});function preview(){const mode=$('#f-mode').value;$('#company-manual').hidden=mode!=='manual';$('#company-timed').style.display=mode==='time'?'grid':'none';let mins=Number($('#f-hours').value)*60;if(mode==='time'){const t=v=>Number(v.slice(0,2))*60+Number(v.slice(3));mins=t($('#f-ended_at').value)-t($('#f-started_at').value)-Number($('#f-break_minutes').value||0)}$('#company-preview').textContent=mins>0?'Valor previsto do serviço: '+money(Math.round(mins*Number($('#f-rate').value)*100/60)):'Confira a duração do serviço.'}for(const sel of ['#f-mode','#f-hours','#f-started_at','#f-ended_at','#f-break_minutes','#f-rate'])$(sel).oninput=preview;$('#f-company_id').onchange=()=>{const c=data.companies.find(c=>c.id===$('#f-company_id').value);$('#f-rate').value=(c.hourly_rate_cents/100).toFixed(2);preview()};preview()}
function companyRuleForm(id){if(!admin())return;const c=data.companies.find(c=>c.id===id),r=data.companyRules.find(r=>r.company_id===id);modal('Repasse da empresa',c.name+' · '+monthLabel(),`<p style="margin-top:18px">Defina o acordo desta empresa. As duas deduções incidem sobre o bruto do serviço.</p><div class="formgrid">${field('tax','Nota / imposto (%)',r?r.tax_bps/100:'','number',true)}${field('room','Sala / custos (%)',r?r.room_bps/100:'','number',true)}${field('share','Percentual do profissional (%)',r?r.share_bps/100:'','number',true)}</div><p class="sub" style="margin-top:15px">Use 0 quando não houver determinada dedução. O cálculo será aplicado aos lançamentos desta empresa no mês selecionado.</p>`,async d=>{const tax=Math.round(Number(d.tax)*100),room=Math.round(Number(d.room)*100),share=Math.round(Number(d.share)*100);if([tax,room,share].some(n=>!Number.isInteger(n)||n<0||n>10000)||tax+room>10000)throw Error('Confira os percentuais.');const res=await client.from('near_test_company_rules').upsert({company_id:id,month:monthDate(),tax_bps:tax,room_bps:room,share_bps:share}).select('company_id').single();if(res.error)throw Error(res.error.message)})}
function companyEarningsTable(rows){return `<div class="card"><h2>Rendimentos de empresas e horas</h2><table><thead><tr><th>Data / empresa</th><th>Horas</th><th>Valor por hora</th><th>Valor do serviço</th><th>Percentual</th><th>Repasse previsto</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${dateBR(r.date)} · ${h(r.company_name)}</td><td>${(r.minutes/60).toLocaleString('pt-BR',{maximumFractionDigits:2})} h</td><td>${money(r.rate_cents)}</td><td>${money(r.gross_cents)}</td><td>${r.share_bps===null?'A definir':r.share_bps/100+'%'}</td><td>${r.commission_cents===null?'A definir':money(r.commission_cents)}</td></tr>`).join('')}</tbody></table><p class="sub" style="margin-top:15px">Os repasses empresariais são previsões. O recebimento e pagamento de repasses empresariais ainda não são controlados por esta tabela.</p></div>`}

boot();
